from ctypes import c_byte

from .message_handling import (SMessageHeader,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32)
from .sack_reflection_interface import SYSTEM_TYPE_KEPLER, CPUA, CPU1, FOUR_BITS
from ..commons import DSP_RESOURCES


@register_message
class BrowserSWVersionReq(RequestMessage):
    id = 0x1b25

    _fields_ = [
        ('header', SMessageHeader),
        ('spare', u32)
    ]


@register_message
class BrowserSWVersionAck(ResponseMessage):
    id = 0x1b26

    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('dataCount', u32),                         # dataCount seems to determine the length of the `version` string
        ('version', c_byte * 100)
    ]


class BrowserSWVersionQuery(Query):
    def __init__(self, req, resp):
        super(BrowserSWVersionQuery, self).__init__(req, resp)

        self.data_count = None  # type: int
        self.version = ''

    def _handle_response(self):
        self.data_count = self.resp_msg.dataCount
        self.version = bytearray(self.resp_msg.version).decode()


class MiscInterface(object):
    def __init__(self, connection):
        self.connection = connection

    sw_version = ''

    def get_browser_sw_version(self, board, cpu, force=False):
        # type: (int, int, bool) -> str

        system_type = DSP_RESOURCES.get_system_type_for_board(board)
        if not self.sw_version or force:
            # substitution for FSMr4 CPU ARM, e.g., cpu=0x3A -> cpu=0x31
            if system_type == SYSTEM_TYPE_KEPLER and (cpu & 0x0F == CPUA):
                cpu = ((cpu >> FOUR_BITS) << FOUR_BITS) + CPU1

            query = BrowserSWVersionQuery(BrowserSWVersionReq(board, cpu), BrowserSWVersionAck())
            qm = BasicQueryManager(query, self.connection)
            qm.send_request_and_wait_for_response()

            self.sw_version = query.version.strip('\x00')

        return self.sw_version
